import { GoogleGenAI, Type } from "@google/genai";

const apiKey = process.env.API_KEY || ''; 
// In a real app, you might want to handle the missing key more gracefully in the UI.
// For this demo, we assume the environment injects it or the user context might provide it if we added that feature.

const ai = new GoogleGenAI({ apiKey });

export const generateSummary = async (resumeContext: string, jobRole?: string): Promise<string> => {
  try {
    const prompt = `
      You are an expert career coach. Write a professional resume summary (3-4 sentences) for a candidate.

      Candidate Context: ${resumeContext}

      ${jobRole ? `Target Job Role: ${jobRole}` : ''}

      The summary should be ATS-friendly, impactful, and highlight key strengths.
      Return ONLY the summary text, no explanations.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 0 }
      }
    });

    return response.text || "Could not generate summary.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Error generating summary. Please check your API key.";
  }
};

export const improveDescription = async (text: string, type: 'experience' | 'project'): Promise<string> => {
  try {
    const prompt = `
      You are an expert resume writer. Improve the following ${type} description to be more professional, impact-oriented, and ATS-friendly.
      Use active verbs and quantify results where possible. Keep the same meaning but make it sound better.

      Current Text:
      "${text}"

      Return ONLY the improved text as bullet points (if applicable) or a paragraph. Do not add conversational filler.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 0 }
      }
    });

    return response.text || text;
  } catch (error) {
    console.error("Gemini API Error:", error);
    return text; // Fallback to original
  }
};

export const tailorResumeToJob = async (currentResumeJSON: string, jobDescription: string): Promise<string> => {
  try {
    const prompt = `
      You are an AI Resume Optimizer. I will provide a resume in JSON format and a Job Description (JD).
      Your task is to tailor the resume to better match the JD while remaining truthful.

      1. Rewrite the summary to align with the JD keywords.
      2. Rewrite experience bullet points to highlight relevant skills found in the JD.
      3. Reorder or highlight skills that match the JD.

      Resume JSON:
      ${currentResumeJSON}

      Job Description:
      ${jobDescription}

      Return the output strictly as a valid JSON object matching the schema of the input resume. 
      Do NOT wrap in markdown code blocks. Just the raw JSON string.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: 'application/json'
      }
    });

    return response.text || "";
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost' | 'danger';
  size?: 'sm' | 'md' | 'lg';
  isLoading?: boolean;
  icon?: React.ReactNode;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  size = 'md', 
  isLoading = false,
  icon,
  className = '',
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center rounded-lg font-medium transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed";

  const variants = {
    primary: "bg-blue-600 text-white hover:bg-blue-700 focus:ring-blue-500 shadow-sm",
    secondary: "bg-indigo-100 text-indigo-700 hover:bg-indigo-200 focus:ring-indigo-500",
    outline: "border border-slate-300 bg-white text-slate-700 hover:bg-slate-50 focus:ring-slate-500",
    ghost: "bg-transparent text-slate-600 hover:bg-slate-100 focus:ring-slate-500",
    danger: "bg-red-600 text-white hover:bg-red-700 focus:ring-red-500",
  };

  const sizes = {
    sm: "px-3 py-1.5 text-xs",
    md: "px-4 py-2 text-sm",
    lg: "px-6 py-3 text-base",
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${sizes[size]} ${className}`} 
      disabled={isLoading || props.disabled}
      {...props}
    >
      {isLoading ? (
        <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-current" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
          <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
          <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
        </svg>
      ) : icon ? (
        <span className="mr-2">{icon}</span>
      ) : null}
      {children}
    </button>
  );
};

