import { GoogleGenAI, Type } from "@google/genai";

const apiKey = process.env.API_KEY || ''; 

const ai = new GoogleGenAI({ apiKey });

export const generateSummary = async (resumeContext: string, jobRole?: string): Promise<string> => {
  try {
    const prompt = `
      You are an expert career coach. Write a professional resume summary (3-4 sentences) for a candidate.

      Candidate Context: ${resumeContext}

      ${jobRole ? `Target Job Role: ${jobRole}` : ''}

      The summary should be ATS-friendly, impactful, and highlight key strengths.
      Return ONLY the summary text, no explanations.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 0 }
      }
    });

    return response.text || "Could not generate summary.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Error generating summary. Please check your API key.";
  }
};

export const improveDescription = async (text: string, type: 'experience' | 'project'): Promise<string> => {
  try {
    const prompt = `
      You are an expert resume writer. Improve the following ${type} description to be more professional, impact-oriented, and ATS-friendly.
      Use active verbs and quantify results where possible. Keep the same meaning but make it sound better.

      Current Text:
      "${text}"

      Return ONLY the improved text as bullet points (if applicable) or a paragraph. Do not add conversational filler.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 0 }
      }
    });

    return response.text || text;
  } catch (error) {
    console.error("Gemini API Error:", error);
    return text; // Fallback to original
  }
};

export const tailorResumeToJob = async (currentResumeJSON: string, jobDescription: string): Promise<string> => {
  try {
    const prompt = `
      You are an AI Resume Optimizer. I will provide a resume in JSON format and a Job Description (JD).
      Your task is to tailor the resume to better match the JD while remaining truthful.

      1. Rewrite the summary to align with the JD keywords.
      2. Rewrite experience bullet points to highlight relevant skills found in the JD.
      3. Reorder or highlight skills that match the JD.

      Resume JSON:
      ${currentResumeJSON}

      Job Description:
      ${jobDescription}

      Return the output strictly as a valid JSON object matching the schema of the input resume. 
      Do NOT wrap in markdown code blocks. Just the raw JSON string.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: 'application/json'
      }
    });

    return response.text || "";
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

export const parseResumeContent = async (text: string): Promise<string> => {
  try {
    const prompt = `
      You are a Resume Parser. Extract information from the provided text and structure it into a JSON object.

      Text to parse:
      "${text}"

      Output Structure (JSON):
      {
        "personalInfo": { "fullName": "", "email": "", "phone": "", "linkedin": "", "portfolio": "", "location": "", "summary": "" },
        "education": [{ "id": "generated-id", "institution": "", "degree": "", "startDate": "", "endDate": "", "gpa": "" }],
        "experience": [{ "id": "generated-id", "company": "", "role": "", "startDate": "", "endDate": "", "description": "" }],
        "projects": [{ "id": "generated-id", "name": "", "technologies": "", "link": "", "description": "" }],
        "skills": ["skill1", "skill2"]
      }

      Ensure all IDs are unique strings. If information is missing, leave it as an empty string.
      Return ONLY valid JSON.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: 'application/json'
      }
    });

    return response.text || "{}";
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

export const generateResumeByRole = async (role: string, level: string): Promise<string> => {
