import React, { useState } from 'react';
import { Button } from './ui/Button';
import { ArrowLeft, Upload, FileText, AlertCircle } from 'lucide-react';
import { parseResumeContent } from '../services/geminiService';
import { Resume } from '../types';

interface ResumeImporterProps {
  onImport: (resume: Resume) => void;
  onBack: () => void;
}

const ResumeImporter: React.FC<ResumeImporterProps> = ({ onImport, onBack }) => {
  const [text, setText] = useState('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [error, setError] = useState('');

  const handleAnalyze = async () => {
    if (!text.trim()) {
      setError('Please paste your resume content first.');
      return;
    }
    setError('');
    setIsAnalyzing(true);

    try {
      const jsonString = await parseResumeContent(text);
      // Clean potential markdown wrapper
      const cleanJson = jsonString.replace(/```json/g, '').replace(/```/g, '').trim();
      const parsedData = JSON.parse(cleanJson);

      // Basic validation/structure check could go here
      const newResume: Resume = {
        id: 'imported-resume',
        name: 'Imported Resume',
        personalInfo: parsedData.personalInfo || {},
        education: parsedData.education || [],
        experience: parsedData.experience || [],
        projects: parsedData.projects || [],
        skills: parsedData.skills || []
      };

      onImport(newResume);
    } catch (err) {
      console.error(err);
      setError('Failed to analyze resume. Please ensure the text is readable and try again.');
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6">
      <div className="w-full max-w-2xl bg-white rounded-xl shadow-xl p-8">

        <div className="flex items-center gap-4 mb-6">
          <button onClick={onBack} className="p-2 hover:bg-slate-100 rounded-full text-slate-500">
            <ArrowLeft size={24} />
          </button>
          <div>
            <h1 className="text-2xl font-bold text-slate-800">Import Existing Resume</h1>
            <p className="text-slate-500 text-sm">Paste your resume text below. Gemini AI will format it for the builder.</p>
          </div>
        </div>

        <div className="mb-6">
          <textarea
            className="w-full h-64 p-4 border border-slate-200 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none text-sm text-slate-700 placeholder:text-slate-400"
            placeholder="Paste your full resume content here (text from PDF or Word)..."
            value={text}
            onChange={(e) => setText(e.target.value)}
          />
          {error && (
            <div className="mt-2 text-red-600 text-sm flex items-center gap-2">
              <AlertCircle size={14} /> {error}
            </div>
          )}
        </div>

        <div className="flex justify-between items-center bg-slate-50 p-4 rounded-lg border border-slate-100">
          <div className="text-xs text-slate-500 max-w-xs">
            <p><strong>Note:</strong> We analyze text only. Images or complex tables might not import perfectly.</p>
          </div>
          <Button 
            onClick={handleAnalyze} 
            isLoading={isAnalyzing} 
            disabled={!text.trim()} 
            icon={<Upload size={18} />}
            size="lg"
          >
            Analyze & Import
          </Button>
        </div>

      </div>
    </div>
  );
};

export default ResumeImporter;

import React, { useState } from 'react';
import { Button } from './ui/Button';
import { ArrowLeft, Sparkles, Briefcase, GraduationCap } from 'lucide-react';
import { generateResumeByRole } from '../services/geminiService';
import { Resume } from '../types';

interface RoleGeneratorProps {
  onGenerate: (resume: Resume) => void;
  onBack: () => void;
}

const RoleGenerator: React.FC<RoleGeneratorProps> = ({ onGenerate, onBack }) => {
  const [role, setRole] = useState('');
  const [level, setLevel] = useState('Entry Level');
  const [isGenerating, setIsGenerating] = useState(false);

  const handleGenerate = async () => {
    if (!role.trim()) return;
    setIsGenerating(true);

    try {
      const jsonString = await generateResumeByRole(role, level);
      const cleanJson = jsonString.replace(/```json/g, '').replace(/```/g, '').trim();
      const parsedData = JSON.parse(cleanJson);

      const newResume: Resume = {
        id: `gen-${Date.now()}`,
        name: `${role} Resume`,
        personalInfo: parsedData.personalInfo || {},
        education: parsedData.education || [],
        experience: parsedData.experience || [],
        projects: parsedData.projects || [],
        skills: parsedData.skills || []
      };

      onGenerate(newResume);
    } catch (err) {
      console.error(err);
      alert('Failed to generate resume. Please try again.');
    } finally {
      setIsGenerating(false);
    }
  };

  const levels = ['Internship', 'Entry Level', 'Junior', 'Mid-Level', 'Senior'];

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6">
      <div className="w-full max-w-lg bg-white rounded-xl shadow-xl p-8">

        <div className="flex items-center gap-4 mb-8">
          <button onClick={onBack} className="p-2 hover:bg-slate-100 rounded-full text-slate-500">
            <ArrowLeft size={24} />
          </button>
          <div>
            <h1 className="text-2xl font-bold text-slate-800">Generate by Role</h1>
            <p className="text-slate-500 text-sm">AI will create a realistic resume draft for you.</p>
          </div>
        </div>

        <div className="space-y-6">

          <div>
            <label className="block text-sm font-medium text-slate-700 mb-2">Target Job Role</label>
            <div className="relative">
              <Briefcase className="absolute left-3 top-3 text-slate-400" size={18} />
              <input
                type="text"
                className="w-full pl-10 pr-4 py-2.5 border border-slate-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-purple-500 outline-none"
                placeholder="e.g. Frontend Developer, Marketing Manager"
                value={role}
                onChange={(e) => setRole(e.target.value)}
              />
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-700 mb-2">Experience Level</label>
            <div className="grid grid-cols-2 md:grid-cols-3 gap-2">
              {levels.map((l) => (
                <button
                  key={l}
                  onClick={() => setLevel(l)}
                  className={`text-sm py-2 px-3 rounded-lg border transition-all ${level === l ? 'bg-purple-100 border-purple-500 text-purple-700 font-medium' : 'bg-white border-slate-200 text-slate-600 hover:border-slate-300'}`}
                >
                  {l}
                </button>
              ))}
            </div>
          </div>

          <div className="pt-4">
            <Button 
              onClick={handleGenerate} 
              isLoading={isGenerating} 
              disabled={!role.trim()} 
              className="w-full !bg-purple-600 hover:!bg-purple-700"
              size="lg"
              icon={<Sparkles size={18} />}
            >
              Generate Draft Resume
            </Button>
            <p className="text-center text-xs text-slate-400 mt-4">
              This process usually takes 5-10 seconds.
            </p>
          </div>

        </div>

      </div>
    </div>
  );
};

export default RoleGenerator;

import React, { useState } from 'react';
import Dashboard from './components/Dashboard';
import Editor from './components/Editor';
import ResumeImporter from './components/ResumeImporter';
import RoleGenerator from './components/RoleGenerator';
import { Resume, AppView } from './types';
import { INITIAL_RESUME, SAMPLE_RESUME } from './constants';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<AppView>(AppView.DASHBOARD);
  const [resume, setResume] = useState<Resume>(INITIAL_RESUME);

  const handleCreateNew = () => {
    setResume(INITIAL_RESUME);
    setCurrentView(AppView.EDITOR);
  };

  const handleLoadSample = () => {
    setResume(SAMPLE_RESUME);
    setCurrentView(AppView.EDITOR);
  };

  const handleImport = () => {
    setCurrentView(AppView.IMPORT);
  };

  const handleRoleGenerate = () => {
    setCurrentView(AppView.ROLE_GENERATOR);
  };

  const handleResumeLoaded = (newResume: Resume) => {
    setResume(newResume);
    setCurrentView(AppView.EDITOR);
  };

  const handleBackToDashboard = () => {
    setCurrentView(AppView.DASHBOARD);
  };

  return (
    <div className="font-sans text-slate-900">
      {currentView === AppView.DASHBOARD && (
        <Dashboard 
          onCreateNew={handleCreateNew} 
          onLoadSample={handleLoadSample}
          onImport={handleImport}
          onGenerate={handleRoleGenerate}
        />
      )}

      {currentView === AppView.IMPORT && (
        <ResumeImporter 
          onImport={handleResumeLoaded}
          onBack={handleBackToDashboard}
        />
      )}

      {currentView === AppView.ROLE_GENERATOR && (
        <RoleGenerator 
          onGenerate={handleResumeLoaded}
          onBack={handleBackToDashboard}
        />
      )}

      {currentView === AppView.EDITOR && (
        <Editor 
          resume={resume} 
          setResume={setResume} 
          onBack={handleBackToDashboard} 
        />
      )}
    </div>
  );
};

export default App;

