import { Resume } from '../types';

interface RoleGeneratorProps {
  onGenerate: (resume: Resume) => void;
  onBack: () => void;
}

const RoleGenerator: React.FC<RoleGeneratorProps> = ({ onGenerate, onBack }) => {
  const [activeTab, setActiveTab] = useState<'scratch' | 'transform'>('scratch');

  // Scratch Mode State
  const [role, setRole] = useState('');
  const [level, setLevel] = useState('Entry Level');

  // Transform Mode State
  const [resumeText, setResumeText] = useState('');
  const [targetRole, setTargetRole] = useState('');

  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState('');

  const cleanJson = (text: string) => text.replace(/```json/g, '').replace(/```/g, '').

  const handleGenerate = async () => {
    setIsGenerating(true);
    setError('');
    try {
      const resume = await generateResumeByRole(role, level);
      if (resume) {
        onGenerate(resume);
      } else {
        setError('Failed to generate resume.');
      }
    } catch (err) {
      console.error(err);
      setError('An unexpected error occurred.');
    } finally {
      setIsGenerating(false);
    }
  };

  const handleParse = async (text: string) => {
    try {
      const response = await parseResumeContent(text);
      const cleaned = cleanJson(response as string);
      return JSON.parse(cleaned);
    } catch (err) {
      console.error(err);
      setError('Failed to parse resume content.');
      return null;
    }
  };

  const handleTransform = async () => {
    setIsGenerating(true);
    setError('');
    try {
      const parsedResume = await handleParse(resumeText);
      if (!parsedResume) {
        setIsGenerating(false);
        return;
      }

      const transformedResume = await transformResumeForRole(parsedResume, targetRole);
      const cleanedTransformedResume = cleanJson(transformedResume as string)
      const parsedTransformedResume = JSON.parse(cleanedTransformedResume)

      onGenerate(parsedTransformedResume as Resume);
    } catch (err) {
      console.error(err);
      setError('An unexpected error occurred during transformation.');
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div>
    {/* UI rendering code is omitted for brevity */}
    </div>
  );
};

export default RoleGenerator;
