    <content><![CDATA[// App.tsx
import React, { useState, useEffect } from 'react';
import './App.css';
import Login from './components/Login';
import ResumeList from './components/ResumeList';
import { useAuth } from './hooks/useAuth';
import { supabaseService } from './services/supabaseService';
import { Resume } from './types/Resume';

function App() {
  const { user, loading, login, logout, signUp } = useAuth();
  const [resumes, setResumes] = useState<Resume[]>([]);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchResumes = async () => {
      if (user) {
        try {
          const fetchedResumes = await supabaseService.getResumes();
          setResumes(fetchedResumes);
        } catch (error: any) {
          setError(error.message || 'Failed to fetch resumes');
        }
      }
    };
    fetchResumes();
  }, [user]);

  const handleLogin = async (email: string, password: string) => {
    try {
      await login(email, password);
    } catch (error: any) {
      setError(error.message || 'Login failed');
    }
  };

  const handleSignUp = async (email: string, password: string) => {
    try {
      await signUp(email, password);
    } catch (error: any) {
      setError(error.message || 'Sign up failed');
    }
  };


  const handleLogout = async () => {
    try {
      await logout();
      setResumes([]);
    } catch (error: any) {
      setError(error.message || 'Logout failed');
    }
  };
  if (loading) {
    return <p>Loading...</p>;
  }

  return (
    <div className="App">
      {error && <p className="text-red-500">{error}</p>}
      {!user ? (
        <Login onLogin={handleLogin} onSignUp={handleSignUp} />
      ) : (
        <>
          <button onClick={handleLogout} className="bg-red-500 hover:bg-red-700 text-white font-bold py-2 px-4 rounded">Logout</button>
          <ResumeList resumes={resumes} />
        </>
      )}
    </div>
  );
}

export default App;
