interface LoginProps {
  onLogin: () => void;
  onGuestLogin: () => void;
}

const Login: React.FC<LoginProps> = ({ onLogin, onGuestLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      if (isLogin) {
        await firebaseService.login(email, password);
        onLogin();
      } else {
        if (!name) {
          setError('Full Name is required for signup');
          setLoading(false);
          return;
        }
        await firebaseService.signUp(email, password, name);
        onLogin();
      }
    } catch (err: any) {
      console.error(err);
      // Handle Firebase specific errors
      const errorMessage = err.message || 'Authentication failed';
      if (err.code === 'auth/email-already-in-use') {
        setError('Email is already in use.');
      } else if (err.code === 'auth/invalid-credential' || err.code === 'auth/wrong-password') {
        setError('Invalid email or password.');
      } else if (err.code === 'auth/weak-password') {
        setError('Password should be at least 6 characters.');
      } else {
        setError(errorMessage);
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-indigo-50 via-purple-50 to-pink-50 flex flex-col items-center justify-center p-4">
